using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.UseCases; using OrcaFacil.Domain.Entities; using OrcaFacil.Infrastructure; using OrcaFacil.Persistence; using OrcaFacil.Persistence.Queries; using OrcaFacil.Persistence.Repositories; using Serilog;
var builder=WebApplication.CreateBuilder(args); builder.Host.UseSerilog((ctx,lc)=>lc.ReadFrom.Configuration(ctx.Configuration).WriteTo.Console()); builder.Services.AddDbContext<OrcaFacilDbContext>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("DefaultConnection"))); builder.Services.AddScoped(typeof(IRepository<>),typeof(EfRepository<>)); builder.Services.AddScoped<IUnitOfWork,UnitOfWork>(); builder.Services.AddScoped<IDocumentQueries,DocumentQueries>(); builder.Services.AddScoped<AuthService>(); builder.Services.AddScoped<DocumentService>(); builder.Services.AddScoped<IPasswordHasher, BCryptPasswordHasher>(); builder.Services.AddScoped<IPdfService, QuestPdfDocumentService>(); builder.Services.AddHealthChecks().AddNpgSql(builder.Configuration.GetConnectionString("DefaultConnection")!); builder.Services.AddAuthentication("OrcaCookie").AddCookie("OrcaCookie",o=>{o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;o.LoginPath="/login";}); builder.Services.AddAuthorization(o=>o.AddPolicy("SuperAdmin",p=>p.RequireRole("SuperAdmin"))); builder.Services.AddRateLimiter(o=>o.AddFixedWindowLimiter("public",l=>{l.PermitLimit=20;l.Window=TimeSpan.FromMinutes(1);})); builder.Services.AddControllers(); builder.Services.AddRazorPages(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddOpenApi();
var app=builder.Build(); if(!app.Environment.IsDevelopment()){app.UseHsts();} app.UseHttpsRedirection(); app.UseMiddleware<CorrelationIdMiddleware>(); app.UseMiddleware<ExceptionHandlingMiddleware>(); app.UseSerilogRequestLogging(); app.UseStaticFiles(); app.UseRouting(); app.UseRateLimiter(); app.UseAuthentication(); app.UseAuthorization(); app.MapHealthChecks("/health"); app.MapGet("/health/version",()=>new{app="OrcaFacil",version="1.0.0",environment=app.Environment.EnvironmentName,date=DateTime.UtcNow}); app.MapControllers(); app.MapRazorPages(); app.MapGet("/",()=>Results.Redirect("/Dashboard")); app.Run();
